    ops.push({ kind: 'addLabel', issue: request, name: IN_REVIEW_LABEL });
  }
  return ops;
}

// THE REST EXECUTOR — what an Actions run does, unchanged in behaviour.
export async function convergeItem(api, gh, repo, plan, { log = console.log } = {}) {
