    } else if (op.kind === 'record') {
      step(`Output this line, on its own, in your reply. Nothing else emits it, and the usage census is read from your transcript:\n\n    ${op.line}\n`);
    } else if (op.kind === 'removeLabel' || op.kind === 'addLabel') {
